def check_inclusion(s1, s2):
    m = len(s1)
    if m > len(s2):
        return False
    need, have = [0] * 26, [0] * 26
    for a, b in zip(s1, s2):
        need[ord(a) - 97] += 1
        have[ord(b) - 97] += 1
    matches = sum(need[i] == have[i] for i in range(26))

    def change(idx, delta):
        nonlocal matches
        matches -= need[idx] == have[idx]
        have[idx] += delta
        matches += need[idx] == have[idx]

    for i in range(m, len(s2)):
        if matches == 26:
            return True
        change(ord(s2[i]) - 97, +1)
        change(ord(s2[i - m]) - 97, -1)
    return matches == 26
